const envelope = $json;
if (!envelope || envelope.type !== 'event.copy.enrichment_requested' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
const event = data.event ?? {};
if (!data.enrichment_id || !data.source_hash || !event.id || !event.title || !event.starts_at) throw new Error('Missing enrichment facts');
const apiKey = String($env.GEMINI_API_KEY || '').trim();
if (!apiKey) throw new Error('GEMINI_API_KEY is not configured');
const model = String($env.GEMINI_MODEL || 'gemini-2.5-flash-lite').trim();
if (!/^[a-zA-Z0-9._-]{1,100}$/.test(model)) throw new Error('Invalid GEMINI_MODEL');
const facts = {
  title: event.title,
  source_description: event.source_description || null,
  city: event.city || null,
  region: event.region || null,
  country_code: event.country_code || null,
  venue: event.venue || null,
  venue_address: event.venue_address || null,
  timezone: event.timezone || null,
  starts_at: event.starts_at,
  ticket_url: event.ticket_url || null,
  bandsintown_event_url: event.bandsintown_event_url || null,
};
const instruction = `Jesteś copywriterem koncertowym zespołu Virya. Na podstawie WYŁĄCZNIE przekazanych faktów napisz po polsku atrakcyjny, konkretny opis wydarzenia do strony koncertu. Maksymalnie 900 znaków, 2-4 krótkie akapity. Nie wymyślaj cen, godzin otwarcia bram, supportów, ograniczeń wiekowych ani żadnych faktów. Nie używaj nagłówka, markdownu, emoji ani hashtagów. Jeżeli źródłowy opis jest skromny, rozbuduj atmosferę i zaproszenie bez dodawania nowych danych. Zwróć wyłącznie JSON zgodny ze schematem.`;
return [{json:{envelope,data,event,model,requestBody:{contents:[{role:'user',parts:[{text:instruction+'\n\nFAKTY JSON:\n'+JSON.stringify(facts)}]}],generationConfig:{temperature:0.55,maxOutputTokens:420,responseMimeType:'application/json',responseSchema:{type:'OBJECT',properties:{description:{type:'STRING'}},required:['description']}}}}}];

const source = $('Validate and build Gemini request').first().json;
const text = $json?.candidates?.[0]?.content?.parts?.map(part => part?.text || '').join('').trim();
if (!text) throw new Error('Gemini returned no description');
let parsed;
try { parsed = JSON.parse(text); } catch { throw new Error('Gemini returned invalid JSON'); }
const description = String(parsed?.description || '').trim();
if (!description || [...description].length > 900 || description.split(/\r?\n/).length > 12) throw new Error('Generated description outside bounds');
if ([...description].some(ch => /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(ch))) throw new Error('Generated description contains control characters');
return [{json:{...source,description,applyBody:{enrichment_id:source.data.enrichment_id,source_hash:source.data.source_hash,language:source.data.language || 'pl',model:source.model,description}}}];

